macro_rules! JoinMap {
    () => {
        # [doc = " A collection of tasks spawned on a Tokio runtime, associated with hash map"] # [doc = " keys."] # [doc = ""] # [doc = " This type is very similar to the [`JoinSet`] type in `tokio::task`, with the"] # [doc = " addition of a  set of keys associated with each task. These keys allow"] # [doc = " [cancelling a task][abort] or [multiple tasks][abort_matching] in the"] # [doc = " `JoinMap` based on   their keys, or [test whether a task corresponding to a"] # [doc = " given key exists][contains] in the `JoinMap`."] # [doc = ""] # [doc = " In addition, when tasks in the `JoinMap` complete, they will return the"] # [doc = " associated key along with the value returned by the task, if any."] # [doc = ""] # [doc = " A `JoinMap` can be used to await the completion of some or all of the tasks"] # [doc = " in the map. The map is not ordered, and the tasks will be returned in the"] # [doc = " order they complete."] # [doc = ""] # [doc = " All of the tasks must have the same return type `V`."] # [doc = ""] # [doc = " When the `JoinMap` is dropped, all tasks in the `JoinMap` are immediately aborted."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Spawn multiple tasks and wait for them:"] # [doc = ""] # [doc = " ```"] # [doc = " use tokio_util::task::JoinMap;"] # [doc = ""] # [doc = " # #[tokio::main(flavor = \"current_thread\")]"] # [doc = " # async fn main() {"] # [doc = " let mut map = JoinMap::new();"] # [doc = ""] # [doc = " for i in 0..10 {"] # [doc = "     // Spawn a task on the `JoinMap` with `i` as its key."] # [doc = "     map.spawn(i, async move { /* ... */ });"] # [doc = " }"] # [doc = ""] # [doc = " let mut seen = [false; 10];"] # [doc = ""] # [doc = " // When a task completes, `join_next` returns the task's key along"] # [doc = " // with its output."] # [doc = " while let Some((key, res)) = map.join_next().await {"] # [doc = "     seen[key] = true;"] # [doc = "     assert!(res.is_ok(), \"task {} completed successfully!\", key);"] # [doc = " }"] # [doc = ""] # [doc = " for i in 0..10 {"] # [doc = "     assert!(seen[i]);"] # [doc = " }"] # [doc = " # }"] # [doc = " ```"] # [doc = ""] # [doc = " Cancel tasks based on their keys:"] # [doc = ""] # [doc = " ```"] # [doc = " use tokio_util::task::JoinMap;"] # [doc = ""] # [doc = " # #[tokio::main(flavor = \"current_thread\")]"] # [doc = " # async fn main() {"] # [doc = " let mut map = JoinMap::new();"] # [doc = ""] # [doc = " map.spawn(\"hello world\", std::future::ready(1));"] # [doc = " map.spawn(\"goodbye world\", std::future::pending());"] # [doc = ""] # [doc = " // Look up the \"goodbye world\" task in the map and abort it."] # [doc = " let aborted = map.abort(\"goodbye world\");"] # [doc = ""] # [doc = " // `JoinMap::abort` returns `true` if a task existed for the"] # [doc = " // provided key."] # [doc = " assert!(aborted);"] # [doc = ""] # [doc = " while let Some((key, res)) = map.join_next().await {"] # [doc = "     if key == \"goodbye world\" {"] # [doc = "         // The aborted task should complete with a cancelled `JoinError`."] # [doc = "         assert!(res.unwrap_err().is_cancelled());"] # [doc = "     } else {"] # [doc = "         // Other tasks should complete normally."] # [doc = "         assert_eq!(res.unwrap(), 1);"] # [doc = "     }"] # [doc = " }"] # [doc = " # }"] # [doc = " ```"] # [doc = ""] # [doc = " [`JoinSet`]: tokio::task::JoinSet"] # [doc = " [abort]: fn@Self::abort"] # [doc = " [abort_matching]: fn@Self::abort_matching"] # [doc = " [contains]: fn@Self::contains_key"] pub struct JoinMap < K , V , S = RandomState > { # [doc = " A map of the [`AbortHandle`]s of the tasks spawned on this `JoinMap`,"] # [doc = " indexed by their keys."] tasks_by_key : HashTable < (K , AbortHandle) > , # [doc = " A map from task IDs to the hash of the key associated with that task."] # [doc = ""] # [doc = " This map is used to perform reverse lookups of tasks in the"] # [doc = " `tasks_by_key` map based on their task IDs. When a task terminates, the"] # [doc = " ID is provided to us by the `JoinSet`, so we can look up the hash value"] # [doc = " of that task's key, and then remove it from the `tasks_by_key` map using"] # [doc = " the raw hash code, resolving collisions by comparing task IDs."] hashes_by_task : HashMap < Id , u64 , S > , # [doc = " The [`JoinSet`] that awaits the completion of tasks spawned on this"] # [doc = " `JoinMap`."] tasks : JoinSet < V > , }
    };
}

JoinMap!()